#!/usr/bin/env python3
"""Generate a package/license/source inventory from a collected DSH runtime ZIP."""
from __future__ import annotations

import argparse
import json
import re
import zipfile
from pathlib import Path
from urllib.parse import quote, urlparse


PREFIX = "lib/node_modules/"
SHIMS = {
    "koffi": "Android inert shim generated by tools/collect_runtime.py; original package replaced.",
    "node-pty": "Android shim generated by tools/collect_runtime.py; original package replaced.",
}
TERMUX_PACKAGES = [
    ("nodejs-lts", "MIT"),
    ("libc++", "NCSA"),
    ("openssl", "Apache-2.0"),
    ("c-ares", "MIT"),
    ("libicu", "custom; see the packaging warning and upstream ICU license"),
    ("libsqlite", "Public Domain"),
    ("zlib", "ZLIB"),
    ("resolv-conf", "Public Domain"),
    ("ca-certificates", "MPL-2.0"),
    ("ripgrep", "MIT"),
    ("pcre2", "BSD 3-Clause"),
]


def clean_cell(value: object) -> str:
    return re.sub(r"\s+", " ", str(value)).replace("|", "\\|").strip()


def package_roots(names: list[str]) -> list[str]:
    roots: set[str] = set()
    for path in names:
        if not path.startswith(PREFIX) or not path.endswith("/package.json"):
            continue
        relative = path[len(PREFIX):]
        parts = relative.split("/")
        if parts[0] == ".bin":
            continue
        if parts[0].startswith("@") and len(parts) > 1:
            roots.add("/".join(parts[:2]))
        else:
            roots.add(parts[0])
    return sorted(roots, key=str.casefold)


def source_url(metadata: dict, name: str) -> str:
    repository = metadata.get("repository")
    url = repository.get("url") if isinstance(repository, dict) else repository
    url = url or metadata.get("homepage")
    if isinstance(url, str):
        url = url.strip()
        if url.startswith("git+"):
            url = url[4:]
        if url.startswith("git://"):
            url = "https://" + url[len("git://"):]
        if url.endswith(".git"):
            url = url[:-4]
        if urlparse(url).scheme in ("http", "https"):
            return url
    return "https://www.npmjs.com/package/" + quote(name, safe="@/")


def generate(runtime_zip: Path) -> str:
    with zipfile.ZipFile(runtime_zip) as archive:
        names = archive.namelist()
        invalid_license_files = []
        for path in names:
            lower_path = path.lower()
            if not ("license" in lower_path or "copying" in lower_path or "copyright" in lower_path or "notice" in lower_path):
                continue
            try:
                content = archive.read(path).lstrip()
            except KeyError:
                continue
            if content.startswith((b"404: Not Found", b"403: Forbidden", b"502 Bad Gateway")):
                invalid_license_files.append(path)
        rows = []
        for root in package_roots(names):
            manifest = f"{PREFIX}{root}/package.json"
            try:
                metadata = json.loads(archive.read(manifest))
            except (KeyError, UnicodeDecodeError, json.JSONDecodeError):
                continue
            name = metadata.get("name") or root
            version = metadata.get("version") or "not declared"
            license_value = metadata.get("license")
            license_text = clean_cell(license_value) if license_value else "Not declared in package.json"
            note = SHIMS.get(root)
            if root in ("@vscode/ripgrep-android-x64", "@vscode/ripgrep-android-arm64"):
                note = "Android package manifest generated by this project; binary comes from Termux ripgrep (MIT)."
            if note:
                license_text += "; " + note
            if root in SHIMS:
                url = "tools/collect_runtime.py"
            elif root in ("@vscode/ripgrep-android-x64", "@vscode/ripgrep-android-arm64"):
                url = "https://github.com/termux/termux-packages/blob/master/packages/ripgrep/build.sh"
            else:
                url = source_url(metadata, name)
            rows.append((name, version, license_text, url))

    rows.sort(key=lambda row: row[0].casefold())
    output = [
        "# Third-Party Notices",
        "",
        f"Generated from `{runtime_zip.as_posix()}`. This inventory covers {len(rows)} top-level npm packages in that runtime ZIP; package versions and license expressions describe the package metadata at collection time.",
        "",
        "This project does not relicense these packages under its MIT License. The runtime archive retains upstream license files where the package provides them; consult the linked package source and the audit notes below for gaps. Termux system packages and native runtime libraries are listed below.",
        "",
        "`Not declared in package.json` means the package manifest does not contain a `license` field; consult the linked upstream project and the package files in the runtime archive before redistributing that component. Android-specific shims created by this repository are identified in the notes column.",
        "",
        "## Termux package closure",
        "",
        "Versions are resolved from the selected architecture's Termux package index during runtime collection. License identifiers below follow the Termux package recipes. The current archive contains invalid HTTP error responses at the expected ICU license paths; the warning below identifies them, and they must be replaced with the upstream ICU license text before redistributing that runtime.",
        "",
        "| Package | Version | License | Termux package recipe |",
        "| --- | --- | --- | --- |",
    ]
    for package, license_text in TERMUX_PACKAGES:
        recipe = f"https://github.com/termux/termux-packages/blob/master/packages/{quote(package, safe='')}/build.sh"
        output.append(
            f"| `{package}` | Resolved at build time | {license_text} | [recipe]({recipe}) |"
        )
    output.extend([
        "",
        "## npm runtime packages",
        "",
        "| Package | Version | Declared license / note | Upstream repository or package page |",
        "| --- | --- | --- | --- |",
    ])
    for name, version, license_text, url in rows:
        output.append(
            f"| `{clean_cell(name)}` | `{clean_cell(version)}` | {clean_cell(license_text)} | [source]({url}) |"
        )
    if invalid_license_files:
        output.extend([
            "",
            "## Packaging warnings",
            "",
            "The following license-like files contain HTTP error responses rather than license text and must not be treated as valid notices:",
            "",
        ])
        output.extend(f"- `{path}`" for path in invalid_license_files)
    output.append("")
    return "\n".join(output)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("runtime_zip", type=Path, help="Collected runtime archive, e.g. app/src/main/assets/runtime.zip")
    parser.add_argument("--output", type=Path, default=Path("THIRD-PARTY-NOTICES.md"))
    args = parser.parse_args()
    if not args.runtime_zip.is_file():
        parser.error(f"runtime ZIP does not exist: {args.runtime_zip}")
    args.output.write_text(generate(args.runtime_zip), encoding="utf-8", newline="\n")
    print(f"Wrote {args.output}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
